const items = $input.all();
const courses = items.filter(item => item.json.id !== 1);
return courses.map(item => ({ json: item.json }));

// A teacher opts a module out of the index by putting this tag in its title.
// Matched case-insensitively anywhere in the title, because the title is written
// by a person: "[no-ai] Lezione 3" and "Lezione 3 [NO-AI]" must both work.
// Set INGEST_OPT_OUT_TAG to an empty string to disable the feature entirely.
const OPT_OUT_TAG = ($env.INGEST_OPT_OUT_TAG ?? '[no-ai]').trim().toLowerCase();

const SUPPORTED_MIMES = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'text/markdown'
];

const courseItem = $('Loop Courses').item;
const courseId = courseItem.json.id;
const rawShortname = courseItem.json.shortname || `course-${courseId}`;
function slugify(s, id) {
  const slug = s
    .normalize('NFD').replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^0-9a-z_-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+|-+$/g, '')
    .substring(0, 50);
  return slug || `course-${id}`;
}
const namespace = slugify(rawShortname, courseId);

const response = $input.first();
const sections = response.json.body || response.json;

// Safety: if Moodle returned an error or unexpected format, abort with _moodleError flag.
// Returning files:[] would cause Dedup&Diff to mark ALL stored files as deleted — catastrophic.
if (!Array.isArray(sections)) {
  const raw = JSON.stringify(sections).slice(0, 200);
  return [{ json: { _moodleError: true, errorDetail: raw, courseId, namespace, files: [] } }];
}

const files = [];
// Counted so Dedup & Diff can tell "no files because a teacher excluded them"
// apart from "no files because Moodle is down" — the two look identical
// downstream, and only the second one must suppress deletions.
let modulesSeen = 0;
let modulesExcluded = 0;
for (const section of sections) {
  if (!section.modules) continue;
  for (const mod of section.modules) {
    if (!mod.contents) continue;
    modulesSeen++;

    // Opt-out wins over everything else this module could contribute: both its
    // documents and, for a page, its transcript.
    if (OPT_OUT_TAG && (mod.name || '').toLowerCase().includes(OPT_OUT_TAG)) {
      modulesExcluded++;
      continue;
    }

    // Page modules carry their HTML body as index.html with a NULL mimetype,
    // so SUPPORTED_MIMES can never match it. Emit it as a transcript
    // candidate; the video id is only discoverable after downloading the HTML.
    // Deliberately NOT followed by `continue`: slide PDFs are attached to page
    // modules alongside index.html, and skipping the loop below would silently
    // stop ingesting all of them.
    if (mod.modname === 'page') {
      const index = mod.contents.find(
        c => c.type === 'file' && c.filename === 'index.html' && c.fileurl
      );
      if (index) {
        files.push({
          _kind: 'page',
          // Visibility is a property of the MODULE, not of the file: hiding a
          // module leaves index.html byte-identical, so this is the only signal
          // that the material must stop being cited.
          hidden: mod.visible === 0,
          fileurl: index.fileurl,
          filename: `${mod.name}.md`,
          uniqueFilename: `mod${mod.id}_transcript.md`,
          filesize: index.filesize,
          timemodified: index.timemodified,
          mimetype: 'text/markdown',
          moduleId: mod.id,
          moduleName: mod.name,
          sectionName: section.name,
          courseId,
          namespace
        });
      }
    }

    for (const content of mod.contents) {
      if (content.type !== 'file') continue;
      if (!SUPPORTED_MIMES.includes(content.mimetype)) continue;
      files.push({
        hidden: mod.visible === 0,
        fileurl: content.fileurl,
        filename: content.filename,
        uniqueFilename: `mod${mod.id}_${content.filename}`,
        filesize: content.filesize,
        timemodified: content.timemodified,
        mimetype: content.mimetype,
        moduleId: mod.id,
        moduleName: mod.name,
        sectionName: section.name,
        courseId,
        namespace
      });
    }
  }
}

return [{ json: { courseId, namespace, files, modulesSeen, modulesExcluded } }];

const fs = require('fs');
const STATE_FILE = $env.STATE_FILE_PATH || '/home/node/.n8n/moodle-ingest-state.json';
function readState() { try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); } catch(e) { return { courseFiles: {} }; } }

const input = $input.first().json;
const namespace = input.namespace;
const courseId = input.courseId;

// Abort if Moodle returned an error — never compute deletions from an empty file list.
if (input._moodleError) {
  return [{ json: { courseId, namespace, toIngest: [], toDelete: [], unchanged: [], _moodleError: true, errorDetail: input.errorDetail, summary: { new: 0, updated: 0, removed: 0, unchanged: 0 } } }];
}

const state = readState();
if (!state.courseFiles) state.courseFiles = {};

const currentFiles = input.files || [];
const storedFiles = state.courseFiles[namespace] || {};

// Safety: if Moodle returned a valid but empty file list while we have stored files,
// something is wrong (course temporarily inaccessible, WS token issue, etc.).
// Skip ALL deletions to avoid wiping Qdrant data on a false signal.
// Threshold is configurable via DELETION_SAFETY_THRESHOLD env var (default 3).
// Set to 0 to disable the safety net entirely.
const parsedThreshold = parseInt($env.DELETION_SAFETY_THRESHOLD ?? '3', 10);
const DELETION_SAFETY_THRESHOLD = Number.isFinite(parsedThreshold) && parsedThreshold >= 0 ? parsedThreshold : 3;
// An empty file list has two very different causes. Moodle being unreachable
// must suppress deletions; a teacher tagging every module in the course must
// NOT — that is the opt-out doing exactly its job, and suppressing it would
// leave the excluded material in the index forever. Extract Files reports how
// many modules it saw and excluded, which is what tells the two apart.
const excludedEmptiedCourse = (input.modulesExcluded || 0) > 0
  && (input.modulesSeen || 0) === (input.modulesExcluded || 0);
if (DELETION_SAFETY_THRESHOLD > 0 && currentFiles.length === 0 && !excludedEmptiedCourse && Object.keys(storedFiles).length >= DELETION_SAFETY_THRESHOLD) {
  console.log(`[Dedup & Diff] Empty-course safety triggered for namespace=${namespace}: ${Object.keys(storedFiles).length} stored files preserved (threshold=${DELETION_SAFETY_THRESHOLD}).`);
  // Populate `unchanged` with minimal entries for each preserved file so the
  // final Ingestion Summary reports the correct unchanged count instead of 0.
  // Without this, the only signal that the safety triggered is the console.log
  // above (visible only in the n8n execution detail, not in the summary).
  const safetyUnchanged = Object.entries(storedFiles).map(([fileurl, stored]) => ({
    fileurl,
    filename: stored.filename,
    uniqueFilename: stored.filename,
    _safetyPreserved: true,
  }));
  return [{ json: { courseId, namespace, toIngest: [], toDelete: [], unchanged: safetyUnchanged, _emptyCourseSafe: true, summary: { new: 0, updated: 0, removed: 0, unchanged: safetyUnchanged.length } } }];
}

const toIngest = [];
const toDelete = [];
const unchanged = [];
const currentFileUrls = new Set(currentFiles.map(f => f.fileurl));

for (const file of currentFiles) {
  const stored = storedFiles[file.fileurl];
  // Visibility belongs in the change signature alongside timemodified. Hiding a
  // module does not touch the file, so timemodified alone would classify the
  // flip as unchanged, the document would never be re-ingested, and its
  // hidden_from_students metadata would stay stale forever — the source would
  // keep being cited to students. Re-ingesting without deleting first does not
  // help: the API returns "exists" on an unchanged content hash and ignores the
  // metadata of that request (measured). The 'updated' branch below already
  // deletes the old document first, which is what makes the flip take effect.
  const storedHidden = stored ? (stored.hidden === true) : false;
  const fileHidden = file.hidden === true;

  if (!stored) {
    toIngest.push({ ...file, action: 'new' });
  } else if (stored.timemodified !== file.timemodified || storedHidden !== fileHidden) {
    toIngest.push({ ...file, action: 'updated', old_document_id: stored.document_id });
  } else {
    unchanged.push({ ...file, action: 'unchanged' });
  }
}

for (const [fileurl, stored] of Object.entries(storedFiles)) {
  if (!currentFileUrls.has(fileurl)) {
    toDelete.push({
      fileurl,
      filename: stored.filename,
      document_id: stored.document_id,
      namespace,
      action: 'removed'
    });
  }
}

return [{
  json: {
    courseId,
    namespace,
    toIngest,
    toDelete,
    unchanged,
    modulesExcluded: input.modulesExcluded || 0,
    summary: {
      new: toIngest.filter(f => f.action === 'new').length,
      updated: toIngest.filter(f => f.action === 'updated').length,
      removed: toDelete.length,
      unchanged: unchanged.length
    }
  }
}];

// Handle all deletions inline and return a single item
const fs = require('fs');
const http = require('http');
const https = require('https');
const { URL } = require('url');
const STATE_FILE = $env.STATE_FILE_PATH || '/home/node/.n8n/moodle-ingest-state.json';
function readState() { try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); } catch(e) { return { courseFiles: {} }; } }
function writeState(s) {
  const tmp = STATE_FILE + '.' + Date.now() + '.' + Math.random().toString(36).slice(2) + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(s));
  fs.renameSync(tmp, STATE_FILE);
}

function httpReq(urlStr, options = {}) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const lib = url.protocol === 'https:' ? https : http;
    const opts = { hostname: url.hostname, port: url.port || (url.protocol === 'https:' ? 443 : 80), path: url.pathname + url.search, method: options.method || 'GET', headers: options.headers || {} };
    const req = lib.request(opts, (res) => { const chunks = []; res.on('data', c => chunks.push(c)); res.on('end', () => resolve({ statusCode: res.statusCode, body: Buffer.concat(chunks) })); });
    req.on('error', reject); req.setTimeout(60000, () => { req.destroy(new Error('Timeout')); });
    if (options.body) req.write(options.body); req.end();
  });
}

const input = $input.first().json;
const state = readState();
const namespace = input.namespace;
const toDelete = input.toDelete || [];

const VEKTRA_API_URL = $env.VEKTRA_API_URL;
const VEKTRA_API_KEY = $env.VEKTRA_API_KEY;

const deleteResults = [];

for (const file of toDelete) {
  if (file.document_id) {
    let deleted = false;
    try {
      const delBody = JSON.stringify({ document_ids: [file.document_id], namespace: file.namespace || namespace });
      const delResp = await httpReq(`${VEKTRA_API_URL}/api/v1/documents/batch`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${VEKTRA_API_KEY}`, 'Content-Length': Buffer.byteLength(delBody) },
        body: delBody,
      });
      if (delResp.statusCode >= 200 && delResp.statusCode < 300) {
        deleteResults.push({ filename: file.filename, status: 'deleted' });
        deleted = true;
      } else {
        deleteResults.push({ filename: file.filename, status: 'delete_failed', error: `HTTP ${delResp.statusCode}: ${delResp.body.toString().substring(0, 100)}` });
      }
    } catch (e) {
      deleteResults.push({ filename: file.filename, status: 'delete_failed', error: e.message });
    }
    // Only forget the file from state when Vektra confirmed the deletion;
    // a transient failure leaves it in state so the next sync retries.
    if (deleted && state.courseFiles && state.courseFiles[namespace]) {
      delete state.courseFiles[namespace][file.fileurl];
    }
  } else if (state.courseFiles && state.courseFiles[namespace]) {
    // No document_id means we never registered it on Vektra — safe to drop.
    delete state.courseFiles[namespace][file.fileurl];
  }
}
writeState(state);

return [{ json: { ...input, deleteResults } }];

// Split toIngest array into individual items for the inner loop
const input = $input.first().json;
const toIngest = input.toIngest || [];
const namespace = input.namespace;
const courseId = input.courseId;

// Pipe delete results as sentinel item — no global static data needed
const deleteSentinel = {
  _isDeleteSummary: true,
  namespace,
  courseId,
  // Course-level, not per-file: how many modules a teacher opted out of the
  // index with the title tag. Carried here because the sentinel is the only
  // course-scoped object that survives the per-file loop.
  modulesExcluded: input.modulesExcluded || 0,
  deleteResults: (input.deleteResults || []).map(d => ({
    file_name: d.filename, namespace, courseId,
    action: 'removed', status: d.status === 'deleted' ? 'completed' : 'failed',
    error: d.error || null
  }))
};

return [
  { json: deleteSentinel },
  ...toIngest.map(file => ({ json: { ...file, namespace, courseId } }))
];

// Process a single file: download from Moodle, upload to Vektra
// Uses native http/https modules to avoid task runner RPC deadlocks
const http = require('http');
const https = require('https');
const { URL } = require('url');
const file = $input.first().json;
if (file._isDeleteSummary) return [{ json: file }];
const namespace = file.namespace;
const courseId = file.courseId;
const uniqueFilename = file.uniqueFilename || `mod${file.moduleId}_${file.filename}`;

const MOODLE_WS_TOKEN = $env.MOODLE_WS_TOKEN;
const VEKTRA_API_URL = $env.VEKTRA_API_URL;
const VEKTRA_API_KEY = $env.VEKTRA_API_KEY;

const fs = require('fs');
const STATE_FILE = $env.STATE_FILE_PATH || '/home/node/.n8n/moodle-ingest-state.json';
function readState() { try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); } catch(e) { return { courseFiles: {} }; } }
function writeState(s) {
  const tmp = STATE_FILE + '.' + Date.now() + '.' + Math.random().toString(36).slice(2) + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(s));
  fs.renameSync(tmp, STATE_FILE);
}

function httpReq(urlStr, options = {}) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const lib = url.protocol === 'https:' ? https : http;
    const opts = {
      hostname: url.hostname, port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search, method: options.method || 'GET',
      headers: options.headers || {},
    };
    const req = lib.request(opts, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve({
        statusCode: res.statusCode,
        headers: res.headers,
        body: Buffer.concat(chunks),
      }));
    });
    req.on('error', reject);
    req.setTimeout(600000, () => { req.destroy(new Error('Request timeout')); });
    if (options.body) req.write(options.body);
    req.end();
  });
}

try {
  // Step 1: Delete old version if update.
  // Bail on non-2xx — proceeding would leave a duplicate document on Vektra.
  if (file.action === 'updated' && file.old_document_id) {
    const delBody = JSON.stringify({ document_ids: [file.old_document_id], namespace });
    const delResp = await httpReq(`${VEKTRA_API_URL}/api/v1/documents/batch`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${VEKTRA_API_KEY}`, 'Content-Length': Buffer.byteLength(delBody) },
      body: delBody,
    });
    if (delResp.statusCode < 200 || delResp.statusCode >= 300) {
      return [{ json: {
        file_name: uniqueFilename, namespace, courseId,
        action: file.action, status: 'failed', document_id: null,
        chunk_count: 0,
        error: `Old-version delete failed (HTTP ${delResp.statusCode}): ${delResp.body.toString().substring(0, 100)}`
      }}];
    }
  }

  // Step 2: Download file from Moodle.
  // Catch HTTP errors (e.g. 502 with HTML body, not just Moodle's JSON error envelope).
  const separator = file.fileurl.includes('?') ? '&' : '?';
  const dlResp = await httpReq(`${file.fileurl}${separator}token=${MOODLE_WS_TOKEN}`);

  if (dlResp.statusCode < 200 || dlResp.statusCode >= 300) {
    return [{ json: {
      file_name: uniqueFilename, namespace, courseId,
      action: file.action, status: 'failed', document_id: null,
      chunk_count: 0,
      error: `Moodle download failed (HTTP ${dlResp.statusCode}): ${dlResp.body.toString().substring(0, 100)}`
    }}];
  }

  if (dlResp.headers['content-type']?.includes('application/json')) {
    return [{ json: {
      file_name: uniqueFilename, namespace, courseId,
      action: file.action, status: 'failed', document_id: null,
      chunk_count: 0, error: 'Download failed: ' + dlResp.body.toString().substring(0, 100)
    }}];
  }

  // Step 2b: page modules carry a YouTube embed rather than a document.
  // Resolve the transcript and upload that instead of the HTML itself.
  let uploadBuffer = dlResp.body;
  let uploadName = uniqueFilename;
  let uploadMime = file.mimetype;

  if (file._kind === 'page') {
    const html = dlResp.body.toString('utf8');
    const match = html.match(
      /\/\/(?:www\.)?youtube(?:-nocookie)?\.com\/embed\/(?!videoseries)([A-Za-z0-9_-]{11})/
    );

    // Roughly half the page modules are slide pages with no video. Their
    // attached PDFs are ingested separately; the page itself is not content.
    if (!match) {
      // If this page previously held a video, Step 1 has already deleted that
      // document. Drop the stale state entry too: leaving it pins the old
      // timemodified, so every later run re-classifies the page as 'updated',
      // re-issues the delete and skips again — a loop that never converges.
      if (file.old_document_id) {
        const state = readState();
        if (state.courseFiles && state.courseFiles[namespace]
            && state.courseFiles[namespace][file.fileurl]) {
          delete state.courseFiles[namespace][file.fileurl];
          writeState(state);
        }
      }
      return [{ json: {
        file_name: uniqueFilename, namespace, courseId,
        action: file.action, status: 'skipped', document_id: null,
        chunk_count: 0,
        error: file.old_document_id
          ? 'Video embed removed from page; previously ingested transcript deleted'
          : null
      }}];
    }

    const videoId = match[1];
    const watchUrl = `https://www.youtube.com/watch?v=${videoId}`;
    const lang = $env.YTDLP_TRANSCRIPT_LANG || 'it';
    const trResp = await httpReq(
      `${$env.YTDLP_API_URL}/api/v1/transcript`
        + `?url=${encodeURIComponent(watchUrl)}`
        + `&lang=${encodeURIComponent(lang)}&source=auto&fmt=text`,
      { headers: { 'X-API-Key': $env.YTDLP_API_KEY } }
    );

    if (trResp.statusCode < 200 || trResp.statusCode >= 300) {
      let detail = `HTTP ${trResp.statusCode}`;
      try {
        const parsed = JSON.parse(trResp.body.toString());
        detail = parsed.detail?.error_code || parsed.error_code || detail;
      } catch (_) { /* non-JSON error body; keep the status code */ }
      return [{ json: {
        file_name: uniqueFilename, namespace, courseId,
        action: file.action, status: 'failed', document_id: null,
        chunk_count: 0,
        error: `Transcript fetch failed for ${videoId}: ${detail}`
      }}];
    }

    // fmt=text inherits the caption file's hard wraps (~37 chars, mid
    // sentence). Collapsing them back into flowing prose keeps chunk
    // boundaries on sentences instead of on subtitle cues.
    const transcript = trResp.body.toString('utf8')
      .replace(/\r\n/g, '\n')
      .replace(/[ \t]*\n[ \t]*/g, ' ')
      .replace(/\s{2,}/g, ' ')
      .trim();

    if (!transcript) {
      return [{ json: {
        file_name: uniqueFilename, namespace, courseId,
        action: file.action, status: 'failed', document_id: null,
        chunk_count: 0, error: `Empty transcript for ${videoId}`
      }}];
    }

    const retrieved = new Date().toISOString().slice(0, 10);
    const markdown = `# ${file.moduleName}\n\n`
      + `Source: ${watchUrl}\n`
      + `Transcript: auto-generated captions (${lang}), retrieved ${retrieved}\n\n`
      + `${transcript}\n`;

    uploadBuffer = Buffer.from(markdown, 'utf8');
    uploadMime = 'text/markdown';
  }

  // Step 3: Upload to Vektra (multipart/form-data)
  const boundary = '----n8nBoundary' + Date.now();
  const filePart = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${uploadName}"\r\nContent-Type: ${uploadMime}\r\n\r\n`;

  // The ingest API takes metadata as one FLAT JSON object in a form field:
  // scalars only, 4 KB max, keys matching ^[a-z][a-z0-9_]{0,63}$.
  // hidden_from_students is sent only when the module is hidden — the backend
  // reads an absent key as false, so omitting it is how a module becomes
  // visible again after a flip.
  const metadata = {};
  if (file.hidden === true) metadata.hidden_from_students = true;
  const metadataPart = Object.keys(metadata).length
    ? `\r\n--${boundary}\r\nContent-Disposition: form-data; name="metadata"\r\n\r\n${JSON.stringify(metadata)}`
    : '';

  const footer = `\r\n--${boundary}--\r\n`;
  const multipartBody = Buffer.concat([
    Buffer.from(filePart),
    uploadBuffer,
    Buffer.from(metadataPart + footer),
  ]);

  const ingestResp = await httpReq(
    `${VEKTRA_API_URL}/api/v1/ingest?namespace=${encodeURIComponent(namespace)}`,
    {
      method: 'POST',
      headers: {
        'Content-Type': `multipart/form-data; boundary=${boundary}`,
        'Authorization': `Bearer ${VEKTRA_API_KEY}`,
        'Content-Length': multipartBody.length,
      },
      body: multipartBody,
    }
  );

  let body;
  try {
    body = JSON.parse(ingestResp.body.toString());
  } catch (_) {
    return [{ json: {
      file_name: uniqueFilename, namespace, courseId,
      action: file.action, status: 'failed', document_id: null,
      chunk_count: 0, error: `Vektra returned non-JSON (HTTP ${ingestResp.statusCode}): ${ingestResp.body.toString().substring(0, 100)}`
    }}];
  }
  const documentId = body.document_id || null;
  const rawStatus = body.status || (ingestResp.statusCode >= 200 && ingestResp.statusCode < 300 ? 'completed' : 'failed');
  const status = (['new', 'exists', 'alias'].includes(rawStatus) && documentId) ? 'completed' : rawStatus;
  const chunkCount = body.chunk_count || 0;
  const error = body.detail?.error?.message || body.error?.message || null;

  // Step 4: Update state on success (file-based persistence)
  if (documentId && status === 'completed') {
    const state = readState();
    if (!state.courseFiles) state.courseFiles = {};
    if (!state.courseFiles[namespace]) state.courseFiles[namespace] = {};
    state.courseFiles[namespace][file.fileurl] = {
      timemodified: file.timemodified,
      // Remembered so the next run can detect a visibility flip, which leaves
      // timemodified untouched.
      hidden: file.hidden === true,
      document_id: documentId,
      filename: uniqueFilename,
      last_synced: new Date().toISOString()
    };
    writeState(state);
  }

  return [{ json: {
    file_name: uniqueFilename, namespace, courseId,
    action: file.action, status, document_id: documentId,
    chunk_count: chunkCount, error
  }}];
} catch (e) {
  return [{ json: {
    file_name: uniqueFilename, namespace, courseId,
    action: file.action, status: 'failed', document_id: null,
    chunk_count: 0, error: e.message?.substring(0, 200)
  }}];
}

// Collapse all file results from inner loop into 1 item
// This ensures Loop Courses advances by exactly 1
const items = $input.all();
const results = items.map(item => item.json);

// Separate sentinel (delete results) from real file results
const sentinel = results.find(r => r._isDeleteSummary);
const deleteItems = sentinel?.deleteResults || [];
const fileResults = results.filter(r => !r._isDeleteSummary);

const allResults = [...deleteItems, ...fileResults];
const modulesExcluded = results.reduce((n, r) => n + (r.modulesExcluded || 0), 0);
return [{ json: { courseResults: allResults, resultCount: allResults.length, modulesExcluded } }];

// No files to ingest — return single item with unchanged and deletion info
const input = $input.first().json;

// When Dedup & Diff propagated _moodleError (Moodle WS returned a non-array
// body for this course), surface a single failed courseResult so the final
// Ingestion Summary increments totalFailed and the operator sees the cause.
// Without this the empty-arrays case below would silently report zeros and
// hide the Moodle outage.
if (input._moodleError) {
  const preview = (input.errorDetail || 'unexpected response').toString().substring(0, 200);
  return [{
    json: {
      courseResults: [{
        file_name: `course-${input.courseId}`,
        namespace: input.namespace,
        courseId: input.courseId,
        action: 'sync',
        status: 'failed',
        error: `Moodle course fetch failed: ${preview}`
      }],
      resultCount: 1
    }
  }];
}

const unchangedFiles = (input.unchanged || []).map(f => ({
  file_name: f.uniqueFilename || f.filename,
  namespace: input.namespace,
  courseId: input.courseId,
  action: 'unchanged',
  status: 'skipped'
}));
const deleteItems = (input.deleteResults || []).map(d => ({
  file_name: d.filename,
  namespace: input.namespace,
  courseId: input.courseId,
  action: 'removed',
  status: d.status === 'deleted' ? 'completed' : 'failed',
  error: d.error || null
}));
const allResults = [...deleteItems, ...unchangedFiles];
return [{ json: { courseResults: allResults, resultCount: allResults.length,
                  modulesExcluded: input.modulesExcluded || 0 } }];

// Aggregate results from all courses
const items = $input.all();

let totalNew = 0, totalUpdated = 0, totalRemoved = 0;
let totalUnchanged = 0, totalFailed = 0;
let totalExcluded = 0;
let totalSkipped = 0;
const details = [];

for (const item of items) {
  // Course-level: modules a teacher opted out of the index by title tag.
  // Reported so an operator can tell the tag working from the extractor broken.
  totalExcluded += item.json.modulesExcluded || 0;
  const results = item.json.courseResults || [item.json];
  for (const d of results) {
    if (d.action === 'new' && (d.status === 'completed' || d.status === 'new')) totalNew++;
    else if (d.action === 'updated' && (d.status === 'completed' || d.status === 'new')) totalUpdated++;
    else if (d.action === 'removed' && d.status === 'completed') totalRemoved++;
    // Order matters: the No Changes node emits unchanged files with
    // action 'unchanged' AND status 'skipped', so the unchanged test has to
    // win. Only pages that carried no video embed reach the skipped test,
    // and those arrive with action 'new' or 'updated'.
    else if (d.action === 'unchanged') totalUnchanged++;
    else if (d.status === 'skipped') totalSkipped++;
    else if (d.status === 'failed' || d.status === 'timeout') totalFailed++;

    if (d.file_name || d.filename) {
      details.push({
        file: d.file_name || d.filename,
        namespace: d.namespace,
        action: d.action || 'unknown',
        status: d.status || 'n/a',
        document_id: d.document_id || null,
        error: d.error || null
      });
    }
  }
}

const summary = `Sync complete: ${totalNew} new, ${totalUpdated} updated, ${totalRemoved} removed, ${totalUnchanged} unchanged, ${totalSkipped} skipped, ${totalExcluded} opted out, ${totalFailed} failed`;
console.log(summary);

return [{
  json: {
    summary,
    totals: { new: totalNew, updated: totalUpdated, removed: totalRemoved, unchanged: totalUnchanged, skipped: totalSkipped, excluded: totalExcluded, failed: totalFailed },
    details
  }
}];
